import java.util.*;

public class Main {
    static final long MOD = 1000000007;
    static long p, k;
    static boolean[] visited;

    static int getCycleLength(int start) {
        int count = 1;
        visited[(int)start] = true;
        int current = (int)start;
        while (!visited[(int)((current * k) % p)]) {
            current = (int)((current * k) % p);
            count++;
            visited[current] = true;
        }
        return count;
    }

    static long binaryPower(long base, long exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        p = sc.nextLong();
        k = sc.nextLong();
        visited = new boolean[(int)p];
        long totalResult = 1;
        for (int i = 1; i < p; i++) {
            if (!visited[i]) {
                int cycleLen = getCycleLength(i);
                long val = binaryPower(k, cycleLen);
                if (val != 1 && val != 0)
                    totalResult = (totalResult * (cycleLen + 1)) % MOD;
                else
                    totalResult = (totalResult * p) % MOD;
            }
        }
        if (k == 1) totalResult = (totalResult * p) % MOD;
        System.out.println(totalResult);
        sc.close();
    }
}
